CREATE TABLE "RawMarketEnvelope" ("id" UUID NOT NULL, "idempotencyKey" TEXT NOT NULL, "venueId" TEXT NOT NULL, "marketId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "eventTime" TIMESTAMPTZ(6), "receivedAt" TIMESTAMPTZ(6) NOT NULL, "processedAt" TIMESTAMPTZ(6) NOT NULL, "sourcePrecision" TEXT NOT NULL, "payload" JSONB NOT NULL, "checksum" TEXT NOT NULL, "createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RawMarketEnvelope_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RawMarketEnvelope_idempotencyKey_key" ON "RawMarketEnvelope"("idempotencyKey");
CREATE INDEX "RawMarketEnvelope_marketId_eventType_eventTime_idx" ON "RawMarketEnvelope"("marketId", "eventType", "eventTime");
CREATE TABLE "MarketTicker" ("id" UUID NOT NULL, "idempotencyKey" TEXT NOT NULL, "marketId" TEXT NOT NULL, "eventTime" TIMESTAMPTZ(6), "receivedAt" TIMESTAMPTZ(6) NOT NULL, "processedAt" TIMESTAMPTZ(6) NOT NULL, "bid" DECIMAL(38,18), "bidQuantity" DECIMAL(38,18), "ask" DECIMAL(38,18), "askQuantity" DECIMAL(38,18), "last" DECIMAL(38,18), "rawEnvelopeId" UUID NOT NULL, CONSTRAINT "MarketTicker_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MarketTicker_idempotencyKey_key" ON "MarketTicker"("idempotencyKey"); CREATE INDEX "MarketTicker_marketId_eventTime_id_idx" ON "MarketTicker"("marketId", "eventTime", "id");
CREATE TABLE "MarketTrade" ("id" UUID NOT NULL, "idempotencyKey" TEXT NOT NULL, "marketId" TEXT NOT NULL, "venueTradeId" TEXT NOT NULL, "side" TEXT NOT NULL, "price" DECIMAL(38,18) NOT NULL, "quantity" DECIMAL(38,18) NOT NULL, "eventTime" TIMESTAMPTZ(6), "receivedAt" TIMESTAMPTZ(6) NOT NULL, "processedAt" TIMESTAMPTZ(6) NOT NULL, "rawEnvelopeId" UUID NOT NULL, CONSTRAINT "MarketTrade_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MarketTrade_idempotencyKey_key" ON "MarketTrade"("idempotencyKey"); CREATE UNIQUE INDEX "MarketTrade_marketId_venueTradeId_key" ON "MarketTrade"("marketId", "venueTradeId"); CREATE INDEX "MarketTrade_marketId_eventTime_id_idx" ON "MarketTrade"("marketId", "eventTime", "id");
CREATE TABLE "MarketCandle" ("id" UUID NOT NULL, "idempotencyKey" TEXT NOT NULL, "marketId" TEXT NOT NULL, "interval" TEXT NOT NULL, "openedAt" TIMESTAMPTZ(6) NOT NULL, "closedAt" TIMESTAMPTZ(6) NOT NULL, "open" DECIMAL(38,18) NOT NULL, "high" DECIMAL(38,18) NOT NULL, "low" DECIMAL(38,18) NOT NULL, "close" DECIMAL(38,18) NOT NULL, "volume" DECIMAL(38,18) NOT NULL, "tradeCount" TEXT, "receivedAt" TIMESTAMPTZ(6) NOT NULL, "processedAt" TIMESTAMPTZ(6) NOT NULL, "rawEnvelopeId" UUID NOT NULL, CONSTRAINT "MarketCandle_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MarketCandle_idempotencyKey_key" ON "MarketCandle"("idempotencyKey"); CREATE UNIQUE INDEX "MarketCandle_marketId_interval_openedAt_key" ON "MarketCandle"("marketId", "interval", "openedAt"); CREATE INDEX "MarketCandle_marketId_interval_openedAt_id_idx" ON "MarketCandle"("marketId", "interval", "openedAt", "id");
ALTER TABLE "MarketTicker" ADD CONSTRAINT "MarketTicker_marketId_fkey" FOREIGN KEY ("marketId") REFERENCES "Market"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "MarketTrade" ADD CONSTRAINT "MarketTrade_marketId_fkey" FOREIGN KEY ("marketId") REFERENCES "Market"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "MarketCandle" ADD CONSTRAINT "MarketCandle_marketId_fkey" FOREIGN KEY ("marketId") REFERENCES "Market"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
